/* ExcelJobMapper.insert */
INSERT INTO ha_excel_job (
      job_id
    , biz_nm
    , file_name
    , worker
    , server_id
    , status
    , processed_rows
    , total_rows
    , file_path
    , params_json
    , columns_json
    , template_id
    , error_msg
    , cancel_yn
    , created_at
    , started_at
    , completed_at
) VALUES (
      #{jobId,        jdbcType=VARCHAR}
    , #{bizNm,        jdbcType=VARCHAR}
    , #{fileName,     jdbcType=VARCHAR}
    , #{worker,       jdbcType=VARCHAR}
    , #{serverId,     jdbcType=VARCHAR}
    , #{status,       jdbcType=VARCHAR}
    , #{processedRows,jdbcType=INTEGER}
    , #{totalRows,    jdbcType=INTEGER}
    , #{filePath,     jdbcType=VARCHAR}
    , #{paramsJson,   jdbcType=LONGVARCHAR}
    , #{columnsJson,  jdbcType=LONGVARCHAR}
    , #{templateId,   jdbcType=VARCHAR}
    , #{errorMsg,     jdbcType=VARCHAR}
    , #{cancelYn,     jdbcType=CHAR}
    , #{createdAt,    jdbcType=BIGINT}
    , #{startedAt,    jdbcType=BIGINT}
    , #{completedAt,  jdbcType=BIGINT}
)

mapper.select:
/* ExcelJobMapper.selectActiveJobId */
SELECT   j.job_id
  FROM   ha_excel_job j
 WHERE   j.worker       =    #{worker,      jdbcType=VARCHAR}
   AND   j.biz_nm       =    #{bizNm,       jdbcType=VARCHAR}
   AND   j.params_json  =    #{paramsJson,  jdbcType=LONGVARCHAR}
   AND   j.columns_json =    #{columnsJson, jdbcType=LONGVARCHAR}
   AND   (
             (j.template_id = #{templateId, jdbcType=VARCHAR})
             OR (j.template_id IS NULL AND #{templateId, jdbcType=VARCHAR} IS NULL)
         )
   AND   j.status       = 'PENDING'
   AND   j.created_at   >=  #{cutoffMs, jdbcType=BIGINT}
 ORDER   BY j.created_at DESC
 LIMIT   1

/* ExcelJobMapper.selectStaleRunningJobIds */
SELECT   j.job_id
  FROM   ha_excel_job j
 WHERE   j.status    = 'RUNNING'
   AND   j.server_id = #{serverId, jdbcType=VARCHAR}

/* ExcelJobMapper.countPendingJobsBefore */
SELECT   COUNT(*)
  FROM   ha_excel_job j
 WHERE   j.status     = 'PENDING'
   AND   j.created_at  <  #{createdAt, jdbcType=BIGINT}

/* ExcelJobMapper.selectExpiredFilePaths */
SELECT   j.file_path
  FROM   ha_excel_job j
 WHERE   j.status      IN ('DONE', 'FAIL')
   AND   j.file_path   IS NOT NULL
   AND   j.completed_at  <  #{cutoffMs, jdbcType=BIGINT}

mapper.update:
/* ExcelJobMapper.tryClaimJob */
UPDATE ha_excel_job
   SET status     = 'RUNNING'
     , server_id  = #{serverId,   jdbcType=VARCHAR}
     , started_at = #{startedAt,  jdbcType=BIGINT}
 WHERE job_id     = #{jobId,      jdbcType=VARCHAR}
   AND status     = 'PENDING'

/* ExcelJobMapper.updateProgress */
UPDATE ha_excel_job
   SET processed_rows = #{processedRows, jdbcType=INTEGER}
     , total_rows     = #{totalRows,     jdbcType=INTEGER}
 WHERE job_id         = #{jobId,         jdbcType=VARCHAR}
   AND status         = 'RUNNING'

/* ExcelJobMapper.updateDone */
UPDATE ha_excel_job
   SET status       = 'DONE'
     , file_path    = #{filePath,    jdbcType=VARCHAR}
     , completed_at = #{completedAt, jdbcType=BIGINT}
 WHERE job_id       = #{jobId,       jdbcType=VARCHAR}
   AND status       = 'RUNNING'

/* ExcelJobMapper.updateFail */
UPDATE ha_excel_job
   SET status       = 'FAIL'
     , error_msg    = #{errorMsg,    jdbcType=VARCHAR}
     , completed_at = #{completedAt, jdbcType=BIGINT}
 WHERE job_id       = #{jobId,       jdbcType=VARCHAR}
   AND status       = 'RUNNING'

/* ExcelJobMapper.failStaleRunningJobs */
UPDATE ha_excel_job
   SET status       = 'FAIL'
     , error_msg    = #{errorMsg,    jdbcType=VARCHAR}
     , completed_at = #{completedAt, jdbcType=BIGINT}
 WHERE status       = 'RUNNING'
   AND server_id    = #{serverId,    jdbcType=VARCHAR}

/* ExcelJobMapper.clearExpiredFilePaths */
UPDATE ha_excel_job
   SET file_path  = NULL
 WHERE status     IN ('DONE', 'FAIL')
   AND file_path  IS NOT NULL
   AND completed_at  <  #{cutoffMs, jdbcType=BIGINT}

/* ExcelJobMapper.cancelPendingJob */
UPDATE ha_excel_job
   SET status       = 'FAIL'
     , error_msg    = #{errorMsg,    jdbcType=VARCHAR}
     , completed_at = #{completedAt, jdbcType=BIGINT}
 WHERE job_id       = #{jobId,       jdbcType=VARCHAR}
   AND status       = 'PENDING'

/* ExcelJobMapper.setCancelRequested */
UPDATE ha_excel_job
   SET cancel_yn = 'Y'
 WHERE job_id    = #{jobId, jdbcType=VARCHAR}
   AND status    = 'RUNNING'

